public class Solution {
  /**
   * 一次遍历把节点摘进三条带哨兵的子链（尾插保序），最后按 < / == / > 串起来。
   * 全程只动 next：既复用原节点，也是 O(1) 额外空间。
   */
  public static ListNode partitionList(ListNode head, int pivot) {
    ListNode loHead = new ListNode(0), loTail = loHead;
    ListNode eqHead = new ListNode(0), eqTail = eqHead;
    ListNode hiHead = new ListNode(0), hiTail = hiHead;
    for (ListNode cur = head; cur != null; ) {
      ListNode next = cur.next;
      cur.next = null; // 先摘干净再接，否则残留指针会把两段接成环
      if (cur.val < pivot) {
        loTail.next = cur;
        loTail = cur;
      } else if (cur.val > pivot) {
        hiTail.next = cur;
        hiTail = cur;
      } else {
        eqTail.next = cur;
        eqTail = cur;
      }
      cur = next;
    }
    loTail.next = eqHead.next != null ? eqHead.next : hiHead.next;
    eqTail.next = hiHead.next;
    return loHead.next != null ? loHead.next : (eqHead.next != null ? eqHead.next : hiHead.next);
  }
}

