import java.util.ArrayList;
import java.util.List;

public class Solution {
  // 图省事的写法：三段各自头插，最后串起来 —— 结果按段反转，审计顺序就没了
  public static ListNode partitionList(ListNode head, int pivot) {
    List<ListNode> lo = new ArrayList<ListNode>();
    List<ListNode> eq = new ArrayList<ListNode>();
    List<ListNode> hi = new ArrayList<ListNode>();
    for (ListNode cur = head; cur != null; cur = cur.next) {
      if (cur.val < pivot) lo.add(0, cur);
      else if (cur.val > pivot) hi.add(0, cur);
      else eq.add(0, cur);
    }
    List<ListNode> all = new ArrayList<ListNode>(lo);
    all.addAll(eq);
    all.addAll(hi);
    ListNode dummy = new ListNode(0), tail = dummy;
    for (ListNode n : all) {
      n.next = null;
      tail.next = n;
      tail = n;
    }
    return dummy.next;
  }
}
